// ASCII Wallpapers: the eight live wallpapers from the claude-wallpapers concept film, behind the chat in Claude Desktop.
// Each wallpaper is an SVG scene (hooks/scenes.js, generated by claude-wallpapers/mod-gen from the film's own scene code)
// with the window's colours and frosted panels to match: dark glass over seven of them, light glass over Cloud Drift.
// /wallpaper opens the picker above the prompt, as /theme does in the film; Clawd the crab sits on it and hops on a pick.
// In a terminal, which draws no look, the scene goes behind the terminal itself: on Konsole (23.08+, Linux) the scene is
// rendered once to an animated WebP (linux/render.ts) and set as the tab's wallpaper (linux/konsole.sh).
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, ThemeSetArgs } from 'claude-code'

import { COLORS } from './colors.js'
import { CARDS, SCENES } from './scenes.js'

const PLUGIN = 'ascii-wallpapers'
// bumped with each rebuild of scenes.js: a new scene name makes the app draw the new picture, not one it kept
const BUILD = 4
type Tone = 'dark' | 'light'
type Wall = { key: keyof typeof SCENES; name: string; tone: Tone; acc: string; alt: string }

// the film's order, names, window tones and accents
const WALLS: Wall[] = [
  { key: 'clawd', name: 'Claude Code', tone: 'dark', acc: '#d97757', alt: 'A spark of ASCII cells turning slowly in a warm glow, code glyphs rising' },
  { key: 'clouds', name: 'Cloud Drift', tone: 'light', acc: '#2f7fd6', alt: 'ASCII clouds drifting over a blue sky, a paper plane gliding through' },
  { key: 'honu', name: 'Honu Lagoon', tone: 'dark', acc: '#2dd4bf', alt: 'A turquoise lagoon from above, sea turtles, a manta and fish swimming in ASCII cells' },
  { key: 'koiPond', name: 'Koi Pond', tone: 'dark', acc: '#ff7a59', alt: 'Koi circling a jade pond under lily pads and drifting petals' },
  { key: 'jellyfish', name: 'Jellyfish', tone: 'dark', acc: '#ff9ad5', alt: 'Glowing jellyfish pulsing up through deep blue water' },
  { key: 'paperBoats', name: 'Paper Boats', tone: 'dark', acc: '#f6f7f2', alt: 'Origami boats drifting on a calm lake, rings spreading behind them' },
  { key: 'fireflies', name: 'Fireflies', tone: 'dark', acc: '#d6ff78', alt: 'Fireflies blinking over a dark meadow, grass swaying' },
  { key: 'moonlit', name: 'Moonlit', tone: 'dark', acc: '#fff3d2', alt: 'A crescent moon, thin clouds sliding past, stars and a shooting star' },
]

// The film's window over a wallpaper: its colours (hooks/colors.js, worked out with Claude Code's makeColors), the panels
// frosted (blur 22) at 55% of the tone.
const GLASS = { dark: { blur: 22, tint: '#0c0c0c', opacity: 0.55 }, light: { blur: 22, tint: '#fafaf8', opacity: 0.55 } }

const looks = new Map<string, ThemeSetArgs>()
function lookOf(w: Wall): ThemeSetArgs {
  let look = looks.get(w.key)
  if (!look) {
    look = { colors: COLORS[w.key], backdrop: { scene: `aw-${w.key}-${BUILD}`, glass: GLASS[w.tone] }, overrideColorScheme: w.tone }
    looks.set(w.key, look)
  }
  return look
}

const current = atom({ plugin: 'ascii-wallpapers', key: 'current' } as const, null)
const picking = atom({ plugin: 'ascii-wallpapers', key: 'picking' } as const, false)
const hops = atom({ plugin: 'ascii-wallpapers', key: 'hops' } as const, 0)
const crab = atom({ plugin: 'ascii-wallpapers', key: 'crab' } as const, true)

// ---------- Clawd, the film's pixel crab: 16 cells wide, two-tone terracotta, legs stepping, a hop and sparks on a pick ----------
const BODY = ['..############..', '..#.########.#..', '..#.########.#..', '..############..', '################', '################', '..############..', '..############..']
const LEGS = ['..#.#......#.#..', '...#.#....#.#...'] as const
function crabSvg(hop: number): string {
  const U = 4, cells = (rows: string[], y0: number) => rows.flatMap((row, j) => [...row].map((c, i) => (c === '#' ? `<rect x="${i * U}" y="${(y0 + j) * U}" width="${U - 0.6}" height="${U - 0.6}" fill="${(i + j) % 2 ? '#d97757' : '#e08566'}"/>` : ''))).join('')
  const sparks = hop ? Array.from({ length: 6 }, (_, k) => { const a = (k / 6) * Math.PI * 2 - Math.PI / 2; return `<text class="sp" style="--x:${(Math.cos(a) * 26).toFixed(1)}px;--y:${(Math.sin(a) * 18).toFixed(1)}px" x="32" y="30">${'✻✢·'.charAt(k % 3)}</text>` }).join('') : ''
  // a fresh hop count is a fresh drawing, so the one-shot hop plays again
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 56" width="64" height="56" data-hop="${hop}"><style>`
    + `.c{animation:${hop ? 'hop .45s cubic-bezier(.3,.7,.4,1) 1,' : ''}bob 2.6s ease-in-out .45s infinite}@keyframes hop{0%,100%{translate:0 0}45%{translate:0 -14px}}@keyframes bob{0%,100%{translate:0 0}50%{translate:0 -1.5px}}`
    + `.l2{animation:st .5s steps(1) infinite}.l1{animation:st .5s steps(1) -.25s infinite}@keyframes st{0%{opacity:1}50%{opacity:0}}`
    + `.sp{font:600 11px ui-monospace,Menlo,monospace;fill:#d97757;text-anchor:middle;animation:sp .6s ease-out 1 forwards}@keyframes sp{from{opacity:1;translate:0 0}to{opacity:0;translate:var(--x) var(--y)}}`
    + `</style><g class="c" transform="translate(0 16)">${cells(BODY, 0)}<g class="l1">${cells([LEGS[0]], 8)}</g><g class="l2">${cells([LEGS[1]], 8)}</g></g>${sparks}<rect x="8" y="53" width="48" height="2" fill="#000" opacity=".25"/></svg>`
}

// ---------- the terminal: the scene behind Konsole's own text ----------
// where the session draws, from session.start: a look draws on desktop and mobile, the terminal needs the helper
let surface: string | null = null
const isTerminal = () => surface !== 'desktop' && surface !== 'mobile'
const rendering = new Set<string>()

async function helper($: EngineInterface, args: string[], timeoutMs = 10_000) {
  const env = await $.process.hookEnv()
  const root = env.CLAUDE_PLUGIN_ROOT
  if (!root) throw new Error('no CLAUDE_PLUGIN_ROOT')
  const ran = await $.process.run(['bash', `${root}/linux/konsole.sh`, ...args], { env: { CLAUDE_PID: env.CLAUDE_PID ?? '' }, timeoutMs })
  return { ok: ran.exitCode === 0, out: ran.stdout.trim(), err: ran.stderr.trim(), root }
}

// the scene behind the Konsole tab; a scene not yet rendered is rendered first, in the background, then shown if it is
// still the pick
async function terminalOn($: EngineInterface, w: Wall): Promise<string> {
  const check = await helper($, ['check'])
  if (!check.ok) return `${w.name} is set, but this terminal can't show it: ${check.err || 'no Konsole'}. Konsole 23.08 or later can.`
  const has = await helper($, ['has', w.key])
  if (!has.ok) {
    if (!rendering.has(w.key)) {
      rendering.add(w.key)
      void (async () => {
        try {
          const dir = (await helper($, ['dir'])).out
          // at the screen's size: konsole.sh then has Konsole draw it 1:1, sharp in a window of any size
          const size = (await helper($, ['screen'])).out.match(/^(\d+)x(\d+)$/)
          const dims = size ? ['--width', size[1] ?? '1920', '--height', size[2] ?? '1080'] : []
          const ran = await $.process.run(['bun', `${has.root}/linux/render.ts`, dir, w.key, ...dims], { timeoutMs: 600_000 })
          if (ran.exitCode !== 0) {
            $.ui.toast(`${w.name} could not be rendered: ${ran.stderr.trim().split('\n').pop() ?? 'unknown error'}`)
            return
          }
          if ((await read($, current)) === w.key) {
            const on = await helper($, ['on', w.key, w.name])
            $.ui.toast(on.ok ? `${w.name} is on.` : `${w.name}: ${on.err}`)
          }
        } catch (err) {
          $.ui.toast(`${w.name} could not be rendered: ${err instanceof Error ? err.message : String(err)}`)
        } finally {
          rendering.delete(w.key)
        }
      })()
    }
    return `Rendering ${w.name} for Konsole, once (a few minutes). It goes on by itself when ready.`
  }
  const on = await helper($, ['on', w.key, w.name])
  return on.ok ? `${w.name} is on.` : `${w.name} is set, but Konsole refused it: ${on.err}`
}

// back to the tab's own scheme; keyed on the surface, not on a flag of this module, which a reload resets
async function terminalOff($: EngineInterface) {
  if (!isTerminal()) return
  await helper($, ['off'], 1_000).catch(() => undefined)
}

async function apply($: EngineInterface, key: string | null, hop = true) {
  const w = WALLS.find(x => x.key === key)
  if (!w) {
    await $.theme.clear()
    await update($, current, () => null)
    await $.store.set('wall', null)
    await terminalOff($)
    return 'Wallpaper off.'
  }
  const set = await $.theme.set(lookOf(w))
  await update($, current, () => w.key)
  await $.store.set('wall', w.key)
  if (hop) await update($, hops, n => n + 1)
  if (set.isDrawn || !isTerminal()) {
    $.ui.status(set.isDrawn ? undefined : `${w.name}: ${set.reason}`)
    return set.isDrawn ? `${w.name} is on.` : `${w.name} is set, but this window doesn't draw wallpapers: ${set.reason}`
  }
  try {
    const said = await terminalOn($, w)
    $.ui.status(undefined)
    return said
  } catch (err) {
    return `${w.name} is set, but the terminal helper failed: ${err instanceof Error ? err.message : String(err)}`
  }
}

// the picker's numbers: 1-8 in the film's order, 0 for off
const DIGIT = /^[0-8]$/
const byDigit = (d: string) => (d === '0' ? null : (WALLS[Number(d) - 1]?.key ?? null))

// Clawd in the terminal: the same 16-cell crab, two cell rows to a line in half blocks, legs stepping with each pick
function crabLines(hop: number): string[] {
  const rows: string[] = [...BODY, LEGS[hop % 2] ?? LEGS[0], '................']
  const lines: string[] = []
  for (let j = 0; j < rows.length; j += 2) {
    const a = rows[j] ?? '', b = rows[j + 1] ?? ''
    lines.push([...a].map((c, i) => (c === '#' ? (b[i] === '#' ? '█' : '▀') : b[i] === '#' ? '▄' : ' ')).join(''))
  }
  return lines
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    surface = e.surface
    await $.command.register({ name: 'wallpaper', description: 'Live ASCII wallpapers behind the chat: pick one, or turn it off', argumentHint: `${WALLS.map(w => w.key).join(' | ')} | off | crab on|off` })
    const saved = await $.store.get('wall')
    if (typeof saved === 'string') await apply($, saved, false)
    if ((await $.store.get('crab')) === false) await update($, crab, () => false)
    return next(e)
  })

  on('command.run', { command: 'wallpaper' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase().replace(/\s+/g, ' ')
    if (!arg) {
      await update($, picking, () => true)
      // the numbers in the reply too: they answer as a prompt of their own (below) even where the band does not draw
      return { text: `Pick a wallpaper above the prompt, or send its number: ${WALLS.map((w, i) => `${i + 1} ${w.name}`).join(' · ')} · 0 off.` }
    }
    if (DIGIT.test(arg)) return { text: await apply($, byDigit(arg)) }
    if (arg === 'crab on' || arg === 'crab off') {
      await update($, crab, () => arg === 'crab on')
      await $.store.set('crab', arg === 'crab on')
      return { text: arg === 'crab on' ? 'Clawd is back.' : 'Clawd is resting.' }
    }
    if (arg === 'off') return { text: await apply($, null) }
    const w = WALLS.find(x => x.key.toLowerCase() === arg || x.name.toLowerCase() === arg || x.name.toLowerCase().replace(/\s/g, '') === arg.replace(/\s/g, ''))
    if (!w) return { text: `No wallpaper "${arg}". One of: ${WALLS.map(x => x.name).join(', ')}, or off.` }
    return { text: await apply($, w.key) }
  })

  // While the picker is open, a prompt that is one digit picks: the band's hotkeys take a bare digit only while they are
  // armed, and one that missed them would otherwise reach the model as a message
  on('prompt.submit', async ($, e, next) => {
    const text = e.text.trim()
    if (e.command || e.isMeta || !DIGIT.test(text) || !(await read($, picking))) return next(e)
    return { drop: await apply($, byDigit(text)) }
  })

  // the terminal goes back to its own look when the session ends; the pick is kept for the next one
  on('session.end', async ($, e, next) => {
    if (typeof (await $.store.get('wall')) === 'string') await terminalOff($)
    return next(e)
  })

  on('ui.render', { component: 'Backdrop' }, ($, e, next) => {
    if (e.props.plugin !== PLUGIN || (e.surface !== 'desktop' && e.surface !== 'mobile')) return next(e)
    const w = WALLS.find(x => `aw-${x.key}-${BUILD}` === e.props.scene)
    if (!w) return next(e)
    const { Svg } = $.ui.resolve(e)
    return <Svg source={SCENES[w.key]} alt={w.alt} isInteractive />
  })

  // the picker, with Clawd on its edge; Clawd alone on the prompt's edge while a wallpaper is on
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const [isPicking, cur, hop, showCrab] = [await read($, picking), await read($, current), await read($, hops), await read($, crab)]
    // the terminal's picker: no pictures, a row of buttons (1-8 in an empty prompt, 0 for off) and Clawd at its edge
    if (e.surface === 'terminal') {
      if (!isPicking) return next(e)
      const { Box, Text, Button } = $.ui.resolve(e)
      return (
        <Box flexDirection="row" gap="sm">
          <Box flexDirection="column" borderStyle="round" paddingX="sm" flexGrow={1}>
            <Box flexDirection="row" justifyContent="space-between">
              <Box flexDirection="row" gap="sm"><Text bold>/wallpaper</Text><Text dimColor>live ASCII behind the terminal (Konsole)</Text></Box>
              <Box flexDirection="row" gap="sm">
                <Button key="off" label="Off" hotkey="0" plain dimColor onPress={() => apply($, null)} />
                <Button key="close" label="Close" role="dismiss" onPress={() => update($, picking, () => false)} />
              </Box>
            </Box>
            <Box flexDirection="row" gap="md" flexWrap="wrap">
              {WALLS.map((w, i) => (
                <Button key={w.key} label={`${w.name}${w.key === cur ? ' ✓' : ''}`} hotkey={String(i + 1)} plain variant={w.key === cur ? 'primary' : 'secondary'} onPress={() => apply($, w.key)} />
              ))}
            </Box>
          </Box>
          {showCrab ? <Box flexDirection="column">{crabLines(hop).map(l => <Text color="#d97757">{l}</Text>)}</Box> : null}
        </Box>
      )
    }
    if (e.surface !== 'desktop' && e.surface !== 'mobile') return next(e)
    if (!isPicking && (!cur || !showCrab)) return next(e)
    const { Box, Text, Button, Svg } = $.ui.resolve(e)
    const clawd = showCrab ? <Box justifyContent="flex-end" paddingX="md"><Svg source={crabSvg(hop)} alt="Clawd the crab" width={64} height={56} /></Box> : <Box />
    if (!isPicking) return clawd
    return (
      <Box flexDirection="column">
        {clawd}
        <Box flexDirection="column" borderStyle="round" paddingX="sm" gap="xs">
          <Box flexDirection="row" justifyContent="space-between">
            <Box flexDirection="row" gap="sm"><Text bold>/wallpaper</Text><Text dimColor>Chat themes</Text></Box>
            <Box flexDirection="row" gap="sm">
              <Button key="off" label="Off" hotkey="0" dimColor onPress={() => apply($, null)} />
              <Button key="close" label="Close" role="dismiss" onPress={() => update($, picking, () => false)} />
            </Box>
          </Box>
          <Box flexDirection="row" gap="sm" flexWrap="wrap">
            {WALLS.map((w, i) => (
              <Box key={w.key} flexDirection="column" gap="xs">
                <Svg source={CARDS[w.key]} alt={w.name} width={128} height={72} />
                <Button key={w.key} label={`${w.name}${w.key === cur ? ' ✓' : ''}`} hotkey={String(i + 1)} variant={w.key === cur ? 'primary' : 'secondary'} onPress={() => apply($, w.key)} />
              </Box>
            ))}
          </Box>
        </Box>
      </Box>
    )
  })
}
